with valid as (select id, store_id, product_id, sale_date, units, units + revenue as revenue_per_unit from store_sales where units > 17) select date_trunc('quarter', sale_date) as quarter_start, store_id, count(distinct id) as distinct_ids, count(distinct store_id) as distinct_store_ids, round(avg(units), 2) as avg_units, percentile_approx(revenue_per_unit, 0.9) as revenue_per_unit_p90, max(units) as max_units, grouping(date_trunc('quarter', sale_date)) as grouping_level from valid group by grouping sets ((date_trunc('quarter', sale_date), store_id), (date_trunc('quarter', sale_date)), ())
